const IMAGE_CACHE = `images-${CACHE_VERSION}`;
const API_CACHE = `api-${CACHE_VERSION}`;

// Ativos estáticos pré-embarcados (app shell)
const PRECACHE_URLS = [
  '/',
  '/index.html',
  '/app.js',
  '/styles/main.css',
  '/images/icon-192.png',
  '/images/icon-512.png',
  '/manifest.json',
  '/fallback.html'
];

// =============================================================================
// FASE DE INSTALAÇÃO — Pré-carregar assets estáticos
// =============================================================================
self.addEventListener('install', (event) => {
  console.log('[SW] Instalação iniciada...');
  event.waitUntil(
    caches.open(STATIC_CACHE)
      .then((cache) => {
        console.log('[SW] Pré-cacheando assets estáticos...');
        return cache.addAll(PRECACHE_URLS);
      })
      .then(() => {
        console.log('[SW] Pré-cacheamento concluído.');
        return self.skipWaiting();
      })
      .catch((error) => {
        console.error('[SW] Erro no pré-cacheamento:', error);
      })
  );
});

// =============================================================================
// FASE DE ATIVAÇÃO — Limpeza de caches antigos
// =============================================================================
